import sys
from datetime import datetime


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def compute_block_price(start_minutes):
    start_time = datetime.fromtimestamp(start_minutes * 60)
    hour = start_time.hour
    if 8 <= hour < 20:
        return 2.50
    return 1.00


def compute_period_price(blocks):
    total = sum(compute_block_price(block * 60) for block in range(1, blocks + 1))
    return min(total, 18.00)


def compute_fee(duration_minutes):
    if duration_minutes <= 30:
        return 0.0
    blocks = (duration_minutes + 59) // 60
    period_count = (blocks + 23) // 24
    total = 0.0
    for i in range(int(period_count)):  # Convert period_count to int before using in range
        start_block = i * 24 + 1
        end_block = min((i + 1) * 24, blocks)
        period_blocks = end_block - start_block + 1
        total += compute_period_price(period_blocks)
    return total


def parse_line(line):
    parts = line.strip().split()
    if len(parts) != 5:
        return None
    plate, entry_date, entry_time, exit_date, exit_time = parts
    try:
        entry = datetime.strptime(f"{entry_date} {entry_time}", "%Y-%m-%d %H:%M")
        exit = datetime.strptime(f"{exit_date} {exit_time}", "%Y-%m-%d %H:%M")
    except ValueError:
        return None
    if exit <= entry:
        return None
    duration = (exit - entry).total_seconds() / 60
    return (plate, duration)


def main():
    totals = {}
    for line in sys.stdin:
        record = parse_line(line)
        if record is None:
            print(f"{record[0]} invalid")
            continue
        plate, duration = record
        fee = compute_fee(duration)
        print(f"{plate} {int(duration // 60)}:{int(duration % 60):02d} {fee:.2f}")
        totals[plate] = totals.get(plate, 0.0) + fee
    print("---")
    valid_plates = {k: v for k, v in totals.items() if v > 0}
    sorted_plates = sorted(
        valid_plates.items(),
        key=lambda x: (-x[1], x[0]),
    )
    for plate, total_fee in sorted_plates:
        print(f"{plate} {len([d for d in totals if d == plate])} {total_fee:.2f}")


if __name__ == "__main__":
    main()
